const {run} = require('/tmp/probe-casing/drv.js');
const {isSkip} = require('/tmp/probe-casing/gen.js');
const S = c=>String.fromCodePoint(c);
function expect(cps){ return Buffer.from(cps.map(S).join('_').toLowerCase()+'\n','utf8'); }
function test(cps){ const r = run(cps.map(S).join('!')); return {ok: r.code===0 && expect(cps).equals(r.out), r}; }
const bad = [];
function bisect(cps){
  if (cps.length===1){ bad.push(cps[0]); return; }
  const m = cps.length>>1;
  for (const half of [cps.slice(0,m), cps.slice(m)]) if(!test(half).ok) bisect(half);
