const {SEP} = require('/tmp/probe-casing/gen.js');
function slugModel(text){
  const arr=[...text]; let pieces=[], cur='';
  for(const ch of arr){ if(SEP.has(ch.codePointAt(0))){ if(cur){pieces.push(cur);cur='';} } else cur+=ch; }
  if(cur)pieces.push(cur);
  if(pieces.length===0) return text.length===0 ? '' : '_';
  return pieces.join('_').toLowerCase();
}
module.exports={slugModel};
