for(let cp=1;cp<=0x10FFFF;cp++){ if(cp>=0xD800&&cp<=0xDFFF) continue; const s=S(cp); if(s.toLowerCase()!==s||s.toUpperCase()!==s) pool.push(cp); }
const marks=[];
for(let cp=0x300;cp<=0x36F;cp++) marks.push(cp);
for(const cp of [0x345,0xAD,0x200B,0x200C,0x200D,0x2060,0xFEFF,0x180E,0x2E,0x27,0x5F,0x20,0x5C,0x7F,0xA0,0x2003,0x2014,0xB7,0x2019,0x02B0,0x02BC,0x1FBE,0x483,0x591,0x5BF,0x610,0x64B,0x670,0x6D6,0xE31,0xE47,0x102E,0x17B4,0x1DC0,0x20D0,0xFE00,0xFE20,0x101FD,0x1D167,0xE0100,0x1F3FB,0x110BD]) marks.push(cp);
console.error('pool',pool.length,'marks',marks.length);
const rnd=n=>Math.floor(Math.random()*n);
let seed=12345; function rand(){ seed=(seed*1103515245+12345)&0x7fffffff; return seed/0x7fffffff; }
function pick(){
  const r=rand();
  if(r<0.55) return pool[Math.floor(rand()*pool.length)];
  if(r<0.85) return marks[Math.floor(rand()*marks.length)];
  if(r<0.90) return [0x3A3,0x3C2,0x3C3,0x130,0xDF,0x1E9E,0x1F88,0xFB03,0x587][Math.floor(rand()*9)];
  let c; do{ c=1+Math.floor(rand()*0x10FFFF); }while(c>=0xD800&&c<=0xDFFF); return c;
}
function cluster(){ const n=1+Math.floor(rand()*6); let s=''; for(let i=0;i<n;i++) s+=S(pick()); return s; }
function test(cl){ const v=cl.join('!'); const r=run(v); const exp=Buffer.from(slugModel(v)+'\n','utf8'); return {ok:r.code===0&&exp.equals(r.out),r,exp,v}; }
const bad=[];
function bisect(cl){ if(cl.length===1){bad.push(cl[0]);return;} const m=cl.length>>1; for(const h of [cl.slice(0,m),cl.slice(m)]) if(!test(h).ok) bisect(h); }
const NB=250, PER=1500;
for(let b=0;b<NB;b++){
  const cl=[]; for(let i=0;i<PER;i++) cl.push(cluster());
  const t=test(cl);
  if(!t.ok){ console.error('batch',b,'mismatch'); bisect(cl); }
}
console.error('done batches',NB,'clusters',NB*PER);
console.log('bad',bad.length);
for(const s of bad.slice(0,60)){
  const r=run(s);
  console.log('IN',Buffer.from(s,'utf8').toString('hex'),'PY',r.out.toString('hex'),'NODE',Buffer.from(slugModel(s)+'\n','utf8').toString('hex'));
}
require('fs').writeFileSync('/tmp/probe-casing/bad3.json',JSON.stringify(bad.map(s=>Buffer.from(s,'utf8').toString('hex'))));

